// Serialized tool-result content only. Host-authored rows and other blocks
// retain their own channel; marker text is never used to infer provenance.
// The explicit whitespace class matches Python re\s (JS omits U+001C..001F
// and U+0085, and adds U+FEFF). The parity corpus is generated by the native helper.
const WS = String.raw`[\u0009-\u000d\u001c-\u0020\u0085\u00a0\u1680\u2000-\u200a\u2028-\u2029\u202f\u205f\u3000]`
const SYSTEM_REMINDER = new RegExp(`<(${WS}*/?${WS}*)system-reminder(${WS}*)>`, 'gi')

export function defangMarkers(text: string): string {
  return text
    .replace(SYSTEM_REMINDER, '<$1system•reminder$2>')
    .replace(/\[(\/?)user interjection/gi, '[$1user•interjection')
    .replace(/\[(\/?)agent message/gi, '[$1agent•message')
    .replace(/\[(\/?)harness notice/gi, '[$1harness•notice')
}

function defangContent(value: unknown): unknown {
  if (typeof value === 'string') return defangMarkers(value)
  if (Array.isArray(value)) return value.map(defangContent)
  if (value !== null && typeof value === 'object') {
    return Object.fromEntries(Object.entries(value).map(([key, part]) => [key, defangContent(part)]))
  }
  return value
}

export function defangToolMessage<T extends { content: unknown[] }>(message: T): T {
  return {
    ...message,
    content: message.content.map(block => {
      if (block === null || typeof block !== 'object' || !('type' in block) || block.type !== 'tool_result') return block
      if (!('content' in block)) return block
      return { ...block, content: defangContent(block.content) }
    }),
  }
}
